function memoryTimestamp(profile:Profile|null,batchId:string){const memory=profile?.memoryLines.find(line=>line.batchId===batchId);if(memory?.createdAt)return new Date(memory.createdAt).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});const count=Number(batchId.replace('swipes-','')),swipe=profile?.swipes[Math.max(0,count-1)];return swipe?new Date(swipe.at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false}):'SAVED';}

export function Meta({meta}:{meta?:CallMeta|null}){return meta?<span className="response-meta"><Glyph name={meta.cached?'refresh':'spark'}/>{meta.offline?'OFFLINE REPLAY':meta.cached?'FROM CACHE':'LIVE RESPONSE'} · {(meta.latencyMs/1000).toFixed(1)}s</span>:null;}
function Rating({stars}:{stars:number}){return <span className="rating" aria-label={`${stars} out of 5 stars`}>{Array.from({length:5},(_,i)=><Glyph key={i} name="star" className={i<stars?'star-filled':'star-empty'}/>)}</span>;}
export function ReviewRow({review}:{review:Review}){return <article className="review-row" id={`review-${review.id}`}><div className="review-top"><Rating stars={review.stars}/><span>{review.id}</span></div><div className="review-byline"><b>{review.author}</b><span>{review.date} · seeded purchase review</span></div><p className="review-sku">{getSku(review.skuId)?.name}</p><h3>{review.title}</h3><p className="review-copy">{review.text}</p>{review.photo&&<span className="photo-badge"><Glyph name="image"/> PHOTO ATTACHED · SEEDED BADGE</span>}<p className="review-helpful">Helpful {review.helpful.toLocaleString()} <span>· seeded count</span></p></article>;}
export function Button({children,onClick,disabled=false,secondary=false,type='button',className=''}:{children:ReactNode;onClick?:()=>void;disabled?:boolean;secondary?:boolean;type?:'button'|'submit';className?:string}){return <button type={type} className={`button ${secondary?'button-secondary':''} ${className}`} disabled={disabled} onClick={onClick}>{actionContent(children)}</button>;}
export function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){const ref=useRef<HTMLElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement|null;ref.current?.querySelector<HTMLButtonElement>('button')?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose();if(event.key==='Tab'){const elements=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a,input,textarea,summary,[tabindex="0"]')||[]);const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);const prevOverflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=prevOverflow;previous?.focus();};},[onClose]);return <div className="modal-layer"><button className="modal-backdrop" onClick={onClose} aria-label="Close panel" tabIndex={-1}/><section className="modal" role="dialog" aria-modal="true" aria-label={title} ref={ref}><div className="modal-header"><span className="eyebrow">{title}</span><button className="close-button" onClick={onClose} aria-label="Close panel"><Glyph name="close"/></button></div>{children}</section></div>;}

